The `_` syntax makes it a bit ugly.

What about adding the templates in a nested attribute + copy it at root level if not defined:

``` js
data.helpers = {};
forEach(templateHelpers, function(method, name) {
  data.helpers[name] = function() {
    return function(value) {
      return method(hogan.compile(value).render(data));
    };
  };
  if (typeof data[name] === 'undefined') {
    data[name] = data.helpers[name];
  }
});
```
